import React from 'react';
import { dayNames } from '../utils/calendarHelpers';

const CalendarHeader = () => {
  return (
    <div className="calendar-header">
      {dayNames.map(day => (
        <div key={day} className="calendar-header-cell">
          {day}
        </div>
      ))}
    </div>
  );
};

export default CalendarHeader;
